<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Service;

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesFilter;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesReadGateway;

final class UserConsentedScopePending
{
    public function __construct(
        private readonly UserConsentedScopesReadGateway $read,
    ) {
    }

    /**
     * Returns the subset of $requestedScopes that have no active consent for the user+client pair.
     *
     * @param string[] $requestedScopes
     *
     * @return string[]
     */
    public function pending(UserRef $user, TrustedClientRef $client, array $requestedScopes): array
    {
        if (!$requestedScopes) {
            return [];
        }

        $filter = (new UserConsentedScopesFilter())
            ->withUser($user)
            ->withTrustedClient($client);

        $grantedScopes = [];
        foreach ($this->read->list($filter)->values() as $consent) {
            if ($consent->isGranted()) {
                $grantedScopes[$consent->getScope()] = true;
            }
        }

        return array_values(
            array_filter($requestedScopes, static fn (string $s): bool => !isset($grantedScopes[$s]))
        );
    }
}
